body.subject #plan { bottom: var(--subjectH, calc(74px + var(--safe))); }
@media (max-height: 720px) { body.subject #plan { opacity: .25; } }
#planCanvas { width: 100%; height: 100%; display: block; cursor: crosshair; touch-action: none; }
#planOut, #planIn {
  position: absolute; z-index: 2; width: 26px; height: 26px; padding: 0;
  border-radius: 8px; background: rgba(10,12,16,.8); border: 1px solid var(--edge);
  color: var(--ink); font-size: 15px; line-height: 1; cursor: pointer;
}
#planOut { top: 6px; left: 6px; }
#dropBtn {
  position: absolute; z-index: 2; top: 6px; left: 70px; width: 26px; height: 26px; padding: 0;
  border-radius: 8px; background: rgba(10,12,16,.8); border: 1px solid var(--edge);
  color: var(--ink); font-size: 15px; line-height: 1; cursor: pointer;
}
#dropBtn.on { background: var(--accent); color: #06231f; border-color: transparent; }
body.day #dropBtn { background: var(--panel); }
#planIn { top: 6px; left: 38px; }
#exploreBtn {
  position: absolute; top: 6px; right: 6px; z-index: 2;
  width: 26px; height: 26px; border-radius: 8px; padding: 0;
  background: rgba(10,12,16,.8); border: 1px solid var(--edge); color: var(--dim);
  font-size: 14px; line-height: 1; cursor: pointer;
}
#exploreBtn.on { color: #06231f; background: var(--accent); border-color: var(--accent); }
/* Choosing ground needs room. While exploring, the plan stops being a glance
   and becomes the thing you are working in, with its controls below it rather
   than on top of the very ground you are trying to read. */
#plan.exploring { width: min(300px, calc(100vw - 24px)); height: min(300px, 42vh); }
#exploreHint {
  position: fixed; right: 12px; z-index: 8;
  bottom: calc(74px + var(--safe) + min(300px, 42vh) + 8px);
  width: min(300px, calc(100vw - 24px));
  font-size: 11.5px; line-height: 1.4; color: var(--ink);
  background: var(--panel); border: 1px solid var(--edge); border-radius: 10px;
  padding: 7px 9px; display: grid; gap: 6px; backdrop-filter: blur(14px);
}
#exploreGo { padding: 6px 9px; font-size: 12px; border-radius: 8px; }

.layerPanel .tick { display: inline-block; width: 14px; color: var(--accent); }
.layerPanel button { font-size: 13px; }

/* ---------------------------------------------------------------- help */
.helpOverlay {
  position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center;
  background: rgba(6,8,11,.72); backdrop-filter: blur(6px); padding: 20px;
}
.helpBox {
  background: var(--panel); border: 1px solid var(--edge); border-radius: 16px;
  padding: 20px 22px; max-width: 520px; width: 100%; max-height: 84vh; overflow: auto;
}
.helpBox h2 { margin: 0 0 14px; font-size: 19px; }
.helpRow { display: grid; grid-template-columns: 120px 1fr; gap: 12px; margin-bottom: 10px; font-size: 13.5px; }
.helpRow b { color: var(--ink); font-weight: 600; }
.helpRow span { color: var(--dim); }
.helpBox .btn { margin-top: 14px; }
@media (max-width: 520px) { .helpRow { grid-template-columns: 1fr; gap: 2px; } }

#waterLegend {
  position: fixed; left: 12px; bottom: calc(74px + var(--safe)); z-index: 6;
  background: rgba(12,14,18,.86); border: 1px solid var(--edge); border-radius: 10px;
  padding: 8px 10px; width: 210px; pointer-events: none;
}
.legendTitle { font-size: 11px; color: var(--ink); margin-bottom: 6px; }
.legendScale { display: flex; height: 8px; border-radius: 3px; overflow: hidden; }
.legendScale i { flex: 1; }
.legendEnds { display: flex; justify-content: space-between; font-size: 10px; color: var(--dim); margin-top: 3px; }
.legendNote { font-size: 10.5px; color: var(--dim); margin-top: 6px; line-height: 1.35; }

#labels { position: fixed; inset: 0; pointer-events: none; }
#labels .label {
  position: absolute; transform: translate(-50%, -100%);
  font-size: 11.5px; padding: 3px 8px; border-radius: 8px;
  background: rgba(12,14,18,.82); border: 1px solid var(--edge); white-space: nowrap;
  max-width: 46vw; overflow: hidden; text-overflow: ellipsis;
}
#labels .label.obs { border-color: rgba(245,184,64,.5); color: #f3ce86; }
#labels .label.street {
  background: none; border: none; padding: 1px 3px; color: #cfd6dc;
  font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase;
  text-shadow: 0 0 4px #000, 0 0 8px #000; transform: translate(-50%, -50%);
}
#labels .label.poi {
  background: rgba(12,14,18,.62); border-color: rgba(214,178,102,.35);
  color: #dcc79a; font-size: 10.5px; padding: 2px 6px;
}
#labels .label.sel { border-color: var(--accent); }

.menu {
  position: fixed; z-index: 30; background: var(--panel); border: 1px solid var(--edge);
  border-radius: 12px; padding: 6px; min-width: 220px; max-height: 60vh; overflow: auto;
  box-shadow: 0 18px 50px rgba(0,0,0,.6);
}
.menu button {
  display: block; width: 100%; text-align: left; padding: 9px 10px; border-radius: 8px;
  background: none; border: none; color: var(--ink); font: inherit; font-size: 13.5px; cursor: pointer;
}
.menu button:hover, .menu button.on { background: rgba(255,255,255,.08); }
.menuLabel { font-size: 12px; color: var(--dim); padding: 6px 10px 4px; }
.nameInput {
  width: calc(100% - 12px); margin: 0 6px 6px; padding: 8px 10px;
  background: rgba(0,0,0,.35); border: 1px solid var(--edge); border-radius: 8px;
  color: var(--ink); font: inherit; font-size: 14px;
}
.nameInput:focus { outline: none; border-color: var(--accent); }
.chip.unset { color: var(--dim); border-style: dashed; }
.importPanel .sub { display: block; font-size: 11.5px; color: var(--dim); }
.importStatus { font-size: 12px; color: var(--dim); padding: 2px 10px 8px; min-height: 16px; }

.btn.primary.danger { background: var(--bad); color: #2a0906; }

#crosshair {
  position: fixed; left: 50%; top: 50%; width: 26px; height: 26px;
  transform: translate(-50%, -50%); pointer-events: none; z-index: 5;
}
#crosshair::before, #crosshair::after {
  content: ''; position: absolute; background: var(--accent); opacity: .9;
}
#crosshair::before { left: 50%; top: 0; width: 1.5px; height: 100%; transform: translateX(-50%); }
#crosshair::after { top: 50%; left: 0; height: 1.5px; width: 100%; transform: translateY(-50%); }
.menu .sub { display: block; font-size: 11.5px; color: var(--dim); }

@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }


/* ---------------------------------------------------------------------------
   Blur is expensive. On a phone every translucent panel over a full-screen
   canvas costs a compositor pass, and the world is what people came to look at.
--------------------------------------------------------------------------- */
@media (max-width: 760px), (pointer: coarse) {
  #tools, section, #sayInput, #say .icon, .menu, .helpOverlay, #attribution, #plan, #waterLegend {
    -webkit-backdrop-filter: none !important;
    backdrop-filter: none !important;
  }
  /* var(--panel), NOT a literal. This hardcoded dark was written when there was
     only one palette, and it quietly outranked the theme: in daylight it made
     every say-bar button a black disc with black glyphs on it. A second place
     that decides a colour is the same fault as a second place that decides a
     height. */
  #tools, section, #sayInput, #say .icon, .menu { background: var(--panel); }
  .helpOverlay { background: rgba(6, 8, 11, .94); }
}

/* Labels are positioned by transform so they never trigger layout. */
#labels .label { left: 0; top: 0; will-change: transform; }

/* A drop target has to say it is one, or nobody tries. */
#sayWrap.dropping { outline: 2px dashed var(--accent); outline-offset: 3px; border-radius: 999px; }

/* The offer to load detail where you are looking. Sits above the say bar,
   because it is about where you are, not about the plan. */
#frameOffer {
  /* An offer must not sit on top of the instrument you would use to judge it.
     Kept clear of the plan on every width, because covering the map to ask
     whether you want more map is absurd. */
  position: fixed; left: 12px; right: calc(24px + 200px); bottom: calc(84px + var(--safe)); z-index: 12;
  max-width: 380px;
  width: min(360px, calc(100vw - 24px));
  background: var(--panel); border: 1px solid var(--edge); border-radius: 12px;
  padding: 10px 12px; display: grid; gap: 8px; backdrop-filter: blur(14px);
  font-size: 12.5px; line-height: 1.45; color: var(--ink);
}
.frameRow { display: flex; gap: 8px; }
.frameRow .btn, .frameRow .tool { padding: 6px 10px; font-size: 12px; border-radius: 8px; }



/* ---------------------------------------------------------------- daylight */
/* One theme switch for the page and the world alike. The dark palette is right
   for a lit room and wrong outdoors, on a phone, or when the subject is the
   shape of land — which people have read off white paper for two centuries. */
body.day {
  --lift: 0 1px 3px rgba(20,22,26,.16), 0 0 0 .5px rgba(20,22,26,.08);
  --bg: #eceae5;
  --panel: rgba(252,251,249,.92);
  --edge: rgba(20,22,26,.16);
  --ink: #14161a;
  --dim: #5c6068;
  --accent: #0e6f60;
}
body.day #top .chip { color: var(--ink); }
body.day .helpOverlay { background: rgba(240,239,236,.94); }
body.day #plan { background: rgba(252,251,249,.9); }
body.day #attribution { background: rgba(252,251,249,.86); color: var(--dim); }
body.day #planOut, body.day #planIn, body.day #exploreBtn {
  background: rgba(252,251,249,.9); color: var(--ink);
}
body.day #exploreBtn.on { background: var(--accent); color: #fff; }
body.day .toast { background: rgba(28,30,34,.94); color: #f4f3f0; }

/* Where you are, in the header rather than floating over the world. */
#top .where { display: flex; align-items: center; gap: 6px; font-variant-numeric: tabular-nums; }
#top .where .sub { color: var(--dim); font-size: 10.5px; }
#compassRose { flex: none; transform-origin: 50% 50%; }
#top .chip.icon { padding: 0; width: 30px; justify-content: center; }
/* Pills at 999px lose their ends to the curve; at 10px the same words fit in
   noticeably less width, which is the whole argument on a phone. */
#top .chip { border-radius: 10px; padding: 5px 9px; }
#top { gap: 6px; }

/* MOBILE: fewer things, bigger. A phone has no room for six small islands, so
   the secondary chips step back and what remains is what you touch. */
@media (max-width: 640px) {
  #top { gap: 6px; flex-wrap: nowrap; overflow: hidden; }
  /* The palette chip STAYS. Hiding the control for choosing the light on the
     one device where the light actually changes — indoors to outdoors, day to
     night — was precisely backwards. The place-search chip steps back instead;
     it is reachable from the place menu. */
  #top .where .sub, #findChip { display: none; }
  #top .where { font-size: 11px; }
  #plan { width: 132px; height: 132px; }
  #plan.exploring { width: min(78vw, 320px); height: min(78vw, 320px); }
  #planOut, #planIn, #exploreBtn { width: 32px; height: 32px; font-size: 17px; }
  /* on a phone there is no room beside the plan, so the offer goes above it */
  #frameOffer { left: 8px; right: 8px; width: auto; max-width: none;
    bottom: calc(84px + var(--safe) + 140px); }
}

/* Paper: the page recedes so the drawing is the only thing with weight. */
body.theme-black {
  --bg: #000; --panel: rgba(14,15,17,.92); --edge: rgba(255,255,255,.22);
  --ink: #f2f4f6; --dim: #9aa1a9; --lift: 0 2px 10px rgba(0,0,0,.8);
}
body.theme-parchment {
  --bg: #e8dfc8; --panel: rgba(250,245,232,.94); --edge: rgba(60,45,20,.24);
  --ink: #241c0e; --dim: #6a5a3c; --accent: #4a5c2a;
}
body.theme-ink {
  --bg: #f7f6f3; --panel: rgba(255,255,255,.95); --edge: rgba(10,10,12,.26);
  --ink: #08090b; --dim: #4a4d52; --accent: #0a4f45;
}
body.paper {
  --bg: #f6f5f2;
  --panel: rgba(255,255,255,.94);
  --edge: rgba(20,22,26,.20);
  --ink: #101215;
  --dim: #575b62;
  --accent: #12564c;
}

/* Chips hold a phrase, not a paragraph. Left to wrap, "Watauga Lake" and "add
   your name" each became two lines and the header grew to four rows on a phone. */
#top .chip { white-space: nowrap; }
#placeName { max-width: 28vw; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 640px) {
  /* The header holds what you cannot work without: where you are, where you
     are looking, and the ability to take back what you just did. Everything
     else is reachable elsewhere and steps aside. */
  #authorChip { max-width: 64px; overflow: hidden; text-overflow: ellipsis; }
  #placeName { max-width: 20vw; }
  #top .chip { padding: 5px 7px; font-size: 12px; }
  #top .icon { width: 32px; height: 32px; }
  #whereAmI { font-size: 10.5px; }
}

/* The palette picker: see the choice before making it. */
.themeMenu button { display: grid; grid-template-columns: 16px 1fr; gap: 8px; align-items: center; }
.themeMenu .swatch { width: 14px; height: 14px; border-radius: 4px; border: 1px solid var(--edge); }
.themeMenu .sub { grid-column: 2; }
#themeChip .swatch {
  width: 15px; height: 15px; border-radius: 4px; border: 1px solid var(--edge); display: block;
}

/* MOBILE: a control you cannot hit is not a control. Forty-four pixels is the
   smallest reliable target on a touchscreen, and several here were thirty. */
@media (max-width: 640px), (pointer: coarse) {
  /* .icon.small is more specific than .icon, so raising .icon alone left the
     entire right-hand rail at thirty-four pixels — the exact controls that are
     hardest to hit on a phone. Name them. */
  .icon, .icon.small { width: 44px; height: 44px; font-size: 19px; }
  #say .icon, #say .icon.small { width: 48px; height: 48px; font-size: 20px; }
  #modeDraw { width: 48px; }
  #modeChip { min-height: 40px; }
  /* A width is only a width if flex cannot take it back. These were set to 40
     and 48 and arrived on screen at 33 and 29, squeezed by their own row. */
  #undoBtn, #redoBtn { width: 40px; flex: 0 0 40px; }
  #modeDraw, #micBtn { flex: 0 0 48px; }
  /* the say row must fit the screen it is on, or its ends fall off the edge */
  #say { left: 8px; right: 8px; gap: 6px; }
  #sayWrap { min-width: 0; }
  #sayInput { min-width: 0; }
  #top .chip { flex: 0 1 auto; min-width: 0; }
  #top .icon, #top .chip.icon { width: 40px; height: 40px; }
  #planOut, #planIn, #exploreBtn, #dropBtn { width: 38px; height: 38px; font-size: 19px; border-radius: 10px; }
  #dropBtn { left: 88px; }
  #top .chip { min-height: 38px; }
  .tool, .btn { min-height: 40px; }
  /* the author is not needed to look at a place; it moves into the place menu */
  #authorChip { display: none; }
}

/* Panels must fit the screen they open on. The import panel was sized for a
   desktop and ran off the bottom of a phone, which is how a search for a
   coordinate ends up looking broken before it has even run. */
.menu { max-height: min(70vh, 560px); overflow-y: auto; overscroll-behavior: contain; }
@media (max-width: 640px), (pointer: coarse) {
  .menu, .importPanel, .findPanel, .themeMenu {
    left: 8px !important; right: 8px !important; width: auto !important;
    max-width: none !important; max-height: 62vh;
  }
  .menu button { min-height: 44px; }
  .importPanel .nameInput, .findPanel .nameInput { min-height: 44px; font-size: 16px; }
}
